 * The instant-runoff count itself: repeatedly tallies ballots for the first
 * still-continuing candidate they name, and eliminates the candidate with the
 * fewest votes when nobody yet has a majority of the active total.
 */

/**
 * Picks which of several candidates tied for fewest votes in the current
 * round gets eliminated, per the backwards-comparison tie-break: compare the
 * tied candidates round by round from the first round, narrowing to whoever
 * had the fewest votes at the first round where they differ, and restarting
 * the comparison from the first round with that narrower set. A tie that
 * survives every round is broken by eliminating whoever sorts last by code
 * point.
 * @param {string[]} tied - candidates tied for fewest votes in the current round
 * @param {{votes: Record<string, number>}[]} roundsSoFar - rounds counted so far, current round included
 */
function pickEliminated(tied, roundsSoFar) {
  let candidates = tied
  while (candidates.length > 1) {
    let narrowed = null
    for (const round of roundsSoFar) {
      const values = candidates.map((name) => round.votes[name])
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        const min = Math.min(...values)
        narrowed = candidates.filter((name) => round.votes[name] === min)
        break
      }
    }
    if (narrowed === null) break
    candidates = narrowed
  }
  if (candidates.length === 1) return candidates[0]
  return [...candidates].sort().at(-1)
}

/**
 * Runs the full count.
 * @returns {{rounds: {votes: Record<string, number>, exhausted: number, eliminated: string|null}[], winner: string|null}}
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const votes = {}
    for (const name of continuing) votes[name] = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const target = ballot.names.find((name) => continuing.has(name))
      if (target === undefined) {
        exhausted += ballot.count
      } else {
        votes[target] += ballot.count
      }
    }

    const activeTotal = Object.values(votes).reduce((sum, v) => sum + v, 0)

    let roundWinner = null
    if (activeTotal > 0) {
      for (const name of continuing) {
        if (votes[name] * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const min = Math.min(...continuing.values().map((name) => votes[name]))
    const tied = [...continuing].filter((name) => votes[name] === min)
    const eliminated = tied.length === 1 ? tied[0] : pickEliminated(tied, [...rounds, { votes }])

    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}
